describe('Element Manager - Add and Delete Elements', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/add_remove_elements/');
  });

  it('should add two elements and verify both delete buttons are created', () => {
    // Click Add Element button twice
    cy.get('button[onclick="addElement()"]').click();
    cy.get('button[onclick="addElement()"]').click();

    // Verify two delete buttons exist
    cy.get('.added-manually').should('have.length', 2);
    cy.get('.added-manually').each(($button) => {
      cy.wrap($button).should('contain', 'Delete');
    });
  });

  it('should delete one element and leave exactly one delete button', () => {
    // Add two elements
    cy.get('button[onclick="addElement()"]').click();
    cy.get('button[onclick="addElement()"]').click();

    // Verify two delete buttons exist
    cy.get('.added-manually').should('have.length', 2);

    // Delete the first element
    cy.get('.added-manually').first().click();

    // Verify exactly one delete button remains
    cy.get('.added-manually').should('have.length', 1);
  });

  it('should handle adding and deleting multiple elements sequentially', () => {
    // Add three elements
    cy.get('button[onclick="addElement()"]').click();
    cy.get('button[onclick="addElement()"]').click();
    cy.get('button[onclick="addElement()"]').click();

    cy.get('.added-manually').should('have.length', 3);

    // Delete first element
    cy.get('.added-manually').first().click();
    cy.get('.added-manually').should('have.length', 2);

    // Delete another element
    cy.get('.added-manually').first().click();
    cy.get('.added-manually').should('have.length', 1);

    // Delete the last element
    cy.get('.added-manually').first().click();
    cy.get('.added-manually').should('have.length', 0);
  });

  it('should handle adding single element and deleting it', () => {
    // Add one element
    cy.get('button[onclick="addElement()"]').click();

    // Verify one delete button exists
    cy.get('.added-manually').should('have.length', 1);

    // Delete the element
    cy.get('.added-manually').click();

    // Verify no delete buttons remain
    cy.get('.added-manually').should('have.length', 0);
  });
});
